enum bunny_core_result_t {
  BUNNY_CORE_OK(0),
  BUNNY_CORE_ERR_INVALID_ARG(1),
  BUNNY_CORE_ERR_NOT_FOUND(2),
  BUNNY_CORE_ERR_DB(3),

  /// an e621/Inkbunny client call failed (network, auth, ...)
  BUNNY_CORE_ERR_SITE(4),
  BUNNY_CORE_ERR_UNKNOWN(5);

  final int value;
  const bunny_core_result_t(this.value);

  static bunny_core_result_t fromValue(int value) => switch (value) {
    0 => BUNNY_CORE_OK,
    1 => BUNNY_CORE_ERR_INVALID_ARG,
    2 => BUNNY_CORE_ERR_NOT_FOUND,
    3 => BUNNY_CORE_ERR_DB,
    4 => BUNNY_CORE_ERR_SITE,
    5 => BUNNY_CORE_ERR_UNKNOWN,
    _ => throw ArgumentError('Unknown value for bunny_core_result_t: $value'),
  };
}

enum bunny_db_site_t {
  BUNNY_DB_SITE_E621(0),
  BUNNY_DB_SITE_INKBUNNY(1);

  final int value;
  const bunny_db_site_t(this.value);

  static bunny_db_site_t fromValue(int value) => switch (value) {
    0 => BUNNY_DB_SITE_E621,
    1 => BUNNY_DB_SITE_INKBUNNY,
    _ => throw ArgumentError('Unknown value for bunny_db_site_t: $value'),
  };
}

