  external ffi.Pointer<ffi.Char> last_run_at;

  /// posts linked to this search with no seen_posts row
  @ffi.Int()
  external int unseen_count;

  /// posts linked to this search, seen or not
  @ffi.Int()
  external int total_count;

  /// queue a favorite for every post this search finds during sync
  @ffi.Bool()
  external bool auto_favorite;

  /// Inkbunny favorite level (1-3); ignored by e621
  @ffi.Int()
  external int auto_favorite_stars;

  /// e621 only -- queue an upvote for every post this search finds during sync
  @ffi.Bool()
  external bool auto_upvote;

  /// shown first in SearchesScreen, ahead of the normal sort order
  @ffi.Bool()
  external bool pinned;

  /// NULL if this search/pool has never been opened
  external ffi.Pointer<ffi.Char> last_viewed_at;

  /// has the (capped) first full scan completed -- see sync.c
  @ffi.Bool()
  external bool initial_sync_done;

  /// highest post id seen by any sync so far; 0 = none yet
  @ffi.Int64()
  external int highest_synced_external_id;

  /// see bunny_db_search_options_t above
  @ffi.Bool()
  external bool uses_default_interval;

  /// the search_groups row this search belongs to; 0 = ungrouped (M21)
  @ffi.Int64()
  external int group_id;
}

/// A folder-like way to organize saved searches in SearchesScreen's tree view
/// (M21) -- flat, not nested. Mirrors bunny_db_search_t.pinned's "shown first"
/// meaning, just at the group level instead of per-search.
final class bunny_db_group_t extends ffi.Struct {
  @ffi.Int64()
  external int id;

  external ffi.Pointer<ffi.Char> name;

  @ffi.Bool()
  external bool pinned;

  external ffi.Pointer<ffi.Char> created_at;
}

final class bunny_db_group_list_t extends ffi.Struct {
  external ffi.Pointer<bunny_db_group_t> items;

  @ffi.Size()
  external int count;
}

final class bunny_db_search_list_t extends ffi.Struct {
  external ffi.Pointer<bunny_db_search_t> items;

