final class bunny_db_post_t extends ffi.Struct {
  /// local db id, stable across syncs
  @ffi.Int64()
  external int id;

  @ffi.UnsignedInt()
  external int siteAsInt;

  bunny_db_site_t get site => bunny_db_site_t.fromValue(siteAsInt);

  /// the site's own post/submission id
  @ffi.Int64()
  external int external_id;

  external ffi.Pointer<ffi.Char> artist;

  external ffi.Pointer<ffi.Char> title;

  external ffi.Pointer<ffi.Char> description;

  external ffi.Pointer<ffi.Char> rating;

  @ffi.Int()
  external int score;

  /// 0 for Inkbunny -- no vote concept there
  @ffi.Int()
  external int score_up;

  /// 0 for Inkbunny -- no vote concept there
  @ffi.Int()
  external int score_down;

  @ffi.Int()
  external int fav_count;

  @ffi.Int()
  external int comment_count;

  external ffi.Pointer<ffi.Char> file_url;

  external ffi.Pointer<ffi.Char> file_ext;

  external ffi.Pointer<ffi.Char> file_md5;

  external ffi.Pointer<ffi.Char> preview_url;

  @ffi.Int()
  external int width;

  @ffi.Int()
  external int height;

  /// the site's own created_at timestamp
  external ffi.Pointer<ffi.Char> created_at_site;

  /// when we last upserted this row
  external ffi.Pointer<ffi.Char> cached_at;

  @ffi.Bool()
  external bool is_seen;

  @ffi.Bool()
  external bool is_favorited;

  /// medium-quality variant (e621's "sample", Inkbunny's "screen"); may be NULL
  external ffi.Pointer<ffi.Char> sample_url;

  /// -1, 0 (no vote), or 1 -- always 0 for Inkbunny (M9.7.1)
  @ffi.Int()
  external int user_vote;
}

final class bunny_db_post_list_t extends ffi.Struct {
  external ffi.Pointer<bunny_db_post_t> items;

  @ffi.Size()
