enum bunny_db_action_type_t {
  BUNNY_DB_ACTION_FAVORITE_ADD(0),
  BUNNY_DB_ACTION_FAVORITE_REMOVE(1),
  BUNNY_DB_ACTION_VOTE(2),
  BUNNY_DB_ACTION_COMMENT(3);

  final int value;
  const bunny_db_action_type_t(this.value);

  static bunny_db_action_type_t fromValue(int value) => switch (value) {
    0 => BUNNY_DB_ACTION_FAVORITE_ADD,
    1 => BUNNY_DB_ACTION_FAVORITE_REMOVE,
    2 => BUNNY_DB_ACTION_VOTE,
    3 => BUNNY_DB_ACTION_COMMENT,
    _ => throw ArgumentError(
      'Unknown value for bunny_db_action_type_t: $value',
    ),
  };
}

enum bunny_db_action_status_t {
  BUNNY_DB_ACTION_STATUS_PENDING(0),
  BUNNY_DB_ACTION_STATUS_DONE(1),
  BUNNY_DB_ACTION_STATUS_FAILED(2);

  final int value;
  const bunny_db_action_status_t(this.value);

  static bunny_db_action_status_t fromValue(int value) => switch (value) {
    0 => BUNNY_DB_ACTION_STATUS_PENDING,
    1 => BUNNY_DB_ACTION_STATUS_DONE,
    2 => BUNNY_DB_ACTION_STATUS_FAILED,
    _ => throw ArgumentError(
      'Unknown value for bunny_db_action_status_t: $value',
    ),
  };
}

final class bunny_db_action_t extends ffi.Struct {
  @ffi.Int64()
  external int id;

  @ffi.Int64()
  external int post_id;

  @ffi.UnsignedInt()
  external int action_typeAsInt;

  bunny_db_action_type_t get action_type =>
      bunny_db_action_type_t.fromValue(action_typeAsInt);

  /// may be NULL; action-specific data, opaque to bunny_db
  external ffi.Pointer<ffi.Char> payload;

  @ffi.UnsignedInt()
  external int statusAsInt;

  bunny_db_action_status_t get status =>
      bunny_db_action_status_t.fromValue(statusAsInt);

  external ffi.Pointer<ffi.Char> created_at;

  /// may be NULL if still pending
  external ffi.Pointer<ffi.Char> attempted_at;

  /// may be NULL
  external ffi.Pointer<ffi.Char> error_message;
}

final class bunny_db_action_list_t extends ffi.Struct {
  external ffi.Pointer<bunny_db_action_t> items;

  @ffi.Size()
  external int count;
}

final class bunny_core extends ffi.Opaque {}

typedef bunny_core_t = bunny_core;
typedef bunny_core_log_fnFunction =
    ffi.Void Function(
      ffi.Pointer<ffi.Void> user_data,
      ffi.Pointer<ffi.Char> level,
      ffi.Pointer<ffi.Char> message,
    );
typedef Dartbunny_core_log_fnFunction =
    void Function(
      ffi.Pointer<ffi.Void> user_data,
      ffi.Pointer<ffi.Char> level,
      ffi.Pointer<ffi.Char> message,
    );

/// Optional sink for human-readable progress/summary lines emitted during
/// bunny_core_sync_due_searches/bunny_core_sync_search (e.g. "Starting full
/// scan for ... (12/700)", "Scanned ... -- found 8 posts, 3 new"). NULL (the
/// default, e.g. standalone/FFI mode) means these lines are simply dropped --
/// there's no log viewer for standalone mode anyway. The server installs one
/// that forwards into its own ring-buffer logger (see server/src/app.c,
/// server/src/log.h). `level` is a short tag like "INFO"; neither pointer is
/// owned by bunny_core.
typedef bunny_core_log_fn =
    ffi.Pointer<ffi.NativeFunction<bunny_core_log_fnFunction>>;

enum bunny_http_result_t {
  BUNNY_HTTP_OK(0),
  BUNNY_HTTP_ERR_INVALID_ARG(1),
  BUNNY_HTTP_ERR_NETWORK(2);

  final int value;
  const bunny_http_result_t(this.value);

  static bunny_http_result_t fromValue(int value) => switch (value) {
    0 => BUNNY_HTTP_OK,
    1 => BUNNY_HTTP_ERR_INVALID_ARG,
    2 => BUNNY_HTTP_ERR_NETWORK,
    _ => throw ArgumentError('Unknown value for bunny_http_result_t: $value'),
  };
}

enum bunny_http_method_t {
  BUNNY_HTTP_GET(0),
  BUNNY_HTTP_POST(1),
  BUNNY_HTTP_PUT(2),
  BUNNY_HTTP_DELETE(3);

  final int value;
  const bunny_http_method_t(this.value);

  static bunny_http_method_t fromValue(int value) => switch (value) {
    0 => BUNNY_HTTP_GET,
    1 => BUNNY_HTTP_POST,
    2 => BUNNY_HTTP_PUT,
    3 => BUNNY_HTTP_DELETE,
    _ => throw ArgumentError('Unknown value for bunny_http_method_t: $value'),
  };
}

final class bunny_http_header_t extends ffi.Struct {
  external ffi.Pointer<ffi.Char> name;

  external ffi.Pointer<ffi.Char> value;
}

final class bunny_http_request_t extends ffi.Struct {
  @ffi.UnsignedInt()
  external int methodAsInt;

  bunny_http_method_t get method => bunny_http_method_t.fromValue(methodAsInt);

  external ffi.Pointer<ffi.Char> url;

  external ffi.Pointer<bunny_http_header_t> headers;

  @ffi.Size()
  external int header_count;

  /// may be NULL; not required to be NUL-terminated, use body_len
  external ffi.Pointer<ffi.Char> body;

  @ffi.Size()
  external int body_len;
}

final class bunny_http_response_t extends ffi.Struct {
  @ffi.Long()
  external int status;

  /// owned by the response, NUL-terminated; free with bunny_http_response_free
  external ffi.Pointer<ffi.Char> body;

  @ffi.Size()
  external int body_len;
}

/// A transport is anything that can turn a request into a response.
/// Production code uses bunny_http_curl_transport(); tests inject a fake
/// transport (e.g. one that serves fixture files keyed by URL) so no unit
/// test ever touches the network.
final class bunny_http_transport_t extends ffi.Struct {
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.UnsignedInt Function(
        ffi.Pointer<ffi.Void> user_data,
        ffi.Pointer<bunny_http_request_t> request,
        ffi.Pointer<bunny_http_response_t> out_response,
      )
    >
  >
  send;

  external ffi.Pointer<ffi.Void> user_data;
}

final class bunny_core_config_t extends ffi.Struct {
  /// required; a filesystem path, or ":memory:" for tests
  external ffi.Pointer<ffi.Char> db_path;

  /// required; e621's API etiquette needs a descriptive UA string
  external ffi.Pointer<ffi.Char> user_agent;

  /// Overrides the HTTP transport used for e621/Inkbunny clients built internally
  /// by bunny_core_sync_due_searches and the action queue. Pass NULL to use the
  /// real curl-backed transport for that site; tests inject fakes here.
  external ffi.Pointer<bunny_http_transport_t> e621_transport;

  external ffi.Pointer<bunny_http_transport_t> inkbunny_transport;

  /// Passed straight through to e621_config_t/inkbunny_config_t's own field
  /// of the same name; 0 => each library's built-in default (~0.5s, real
  /// rate limiting). Tests set a negligible value so a sync pass that
  /// touches both sites doesn't take the better part of a second.
  @ffi.Double()
  external double min_request_interval_sec;

  /// see bunny_core_log_fn above; NULL = no-op
  external bunny_core_log_fn log_callback;

  external ffi.Pointer<ffi.Void> log_user_data;
}

/// A pool's own metadata, fetched live (e621 only -- no persistence, no
/// equivalent on Inkbunny). Used to auto-fill a pool search's label at
/// creation time, and to show the pool's own description (M26) -- the
/// pool's posts themselves are fetched via a normal tag search for
/// "pool:<id>" (bunny_core_search_create), not through this.
final class bunny_core_pool_info_t extends ffi.Struct {
  @ffi.Int64()
  external int id;

  external ffi.Pointer<ffi.Char> name;

  /// e621's own dtext markup, verbatim; NULL if empty
  external ffi.Pointer<ffi.Char> description;

  @ffi.Int64()
  external int post_count;

  /// Every "pool #<N>" mention found in `description` (M26) -- e621 pool
  /// descriptions routinely cross-reference related/continuation pools
  /// this way (see bunny_core_fetch_pool's doc comment). In first-seen
  /// order, duplicates included. Empty when description has none or is
  /// NULL.
  external ffi.Pointer<ffi.Int64> referenced_pool_ids;

  @ffi.Size()
  external int referenced_pool_id_count;
}

/// A post's existing comments, fetched live (e621 only -- no persistence, no
/// equivalent on Inkbunny, same reasoning as bunny_core_pool_info_t above).
/// Takes the local post id (not the site's external id) and looks up the
/// post's own site/external_id internally, matching every other per-post
/// read wrapper in this header.
final class bunny_core_comment_t extends ffi.Struct {
  @ffi.Int64()
  external int id;

  external ffi.Pointer<ffi.Char> creator_name;

  external ffi.Pointer<ffi.Char> body;

  external ffi.Pointer<ffi.Char> created_at;
}

final class bunny_core_comment_list_t extends ffi.Struct {
  external ffi.Pointer<bunny_core_comment_t> items;

  @ffi.Size()
  external int count;
}

